@media (hover: hover) and (pointer: fine) {
  .fd-button:hover:not(:disabled) {
    color: var(--fd-paper);
  }
  .fd-button:hover:not(:disabled)::before {
    transform: none;
  }
  .fd-button:hover svg {
    transform: translate(2px, -2px);
  }
  .fd-text-link:hover::after {
    transform: scaleX(1);
  }
  .fd-text-link:hover svg {
    transform: translate(3px, -3px);
  }
  .fd-map-pin:hover {
    transform: translateY(-6px);
  }
  .fd-filters button:hover:not([aria-pressed="true"]) {
    background: var(--fd-stone);
    transform: translateY(-2px);
  }
  .fd-project-card:hover {
    transform: translateY(-6px);
  }
  .fd-project-card:hover::after {
    opacity: 1;
  }
  .fd-project-card:hover .fd-project-art {
    transform: translateY(-4px) scale(1.045);
  }
  .fd-project-card:hover .fd-card-round {
    background: var(--tone);
    transform: rotate(45deg);
  }
  .fd-project-card:hover .fd-project-link svg {
    transform: translateX(5px);
  }
  .fd-story-step:hover {
    opacity: 1;
    transform: translateX(4px);
  }
  .fd-story-arrows button:hover {
    background: var(--fd-sage);
    transform: translateY(-2px);
  }
  .fd-quote:hover {
    transform: translateY(-4px);
  }
  .fd-faq summary:hover .fd-faq-plus {
    transform: rotate(90deg);
  }
  .fd-pause:hover {
    transform: translateY(-2px);
  }
}

@media (prefers-reduced-motion: no-preference) {
  .fd-header > a,
  .fd-header > nav {
    animation: fd-settle var(--dur-slow) var(--ease-out-expo) both;
  }
  .fd-hero h1 .fd-line > span {
    animation: fd-mask var(--dur-hero) var(--ease-out-expo) both;
    animation-delay: calc(var(--stagger) * 2);
  }
  .fd-hero h1 .fd-line:nth-child(2) > span {
    animation-delay: calc(var(--stagger) * 3);
  }
  .fd-hero-enter {
    animation: fd-settle var(--dur-slow) var(--ease-out-expo) both;
    animation-delay: calc(var(--stagger) * 5);
  }
  .fd-hero-copy > .fd-eyebrow {
    animation-delay: var(--stagger);
  }
  .fd-campus-image {
    animation: fd-campus-arrive var(--dur-hero) var(--ease-out-expo) both;
    animation-delay: calc(var(--stagger) * 3);
  }
  .fd-map-pin {
    animation: fd-settle var(--dur-slow) var(--ease-out-expo) both;
    animation-delay: calc(var(--stagger) * 11);
  }
  .fd-pin-two {
    animation-delay: calc(var(--stagger) * 13);
  }
  .fd-campus-note {
    animation: fd-note 8s ease-in-out infinite;
  }
  [data-fd-paused="true"] .fd-campus-note,
  [data-fd-hidden="true"] .fd-campus-note,
  [data-away="true"] .fd-campus-note {
    animation-play-state: paused;
  }
  [data-fd-motion="full"] [data-reveal] {
    transition:
      opacity var(--dur-slow) var(--ease-out),
      transform var(--dur-slow) var(--ease-out),
      clip-path var(--dur-slow) var(--ease-out);
    transition-delay: calc(var(--i, 0) * var(--stagger));
  }
  [data-fd-motion="full"] [data-reveal]:not([data-in="true"]) {
    opacity: 0;
    transform: translateY(var(--reveal-shift));
  }
  [data-fd-motion="full"] [data-reveal="mask"]:not([data-in="true"]) {
    clip-path: inset(0 0 100% 0);
    transform: translateY(15px);
  }
  [data-fd-motion="full"] [data-reveal="wipe"]:not([data-in="true"]) {
    clip-path: inset(0 0 100% 0);
    transform: scale(1.025);
  }
  [data-fd-motion="full"] [data-reveal="draw"]:not([data-in="true"]) {
    transform: scaleX(0.85);
    transform-origin: left;
  }
  [data-fd-motion="full"] [data-reveal="card"]:not([data-in="true"]) {
    transform: translateY(32px) scale(0.97);
  }
  .fd-project-grid {
    animation: fd-settle var(--dur-base) var(--ease-out);
  }
  .fd-dialog[open] {
    animation: fd-dialog-arrive var(--dur-base) var(--ease-out-expo);
  }
  .fd-dialog[open]::backdrop {
    animation: fd-backdrop var(--dur-fast) var(--ease-out);
  }
  .fd-success {
    animation: fd-settle var(--dur-slow) var(--ease-out-expo);
  }
  .fd-success > svg {
    animation: fd-door var(--dur-slow) var(--ease-out-expo);
  }
  .fd-field:has([aria-invalid="true"]) {
    animation: fd-shake var(--dur-base) var(--ease-out);
  }
  .fd-faq[open] .fd-faq-answer {
    animation: fd-answer var(--dur-base) var(--ease-out);
  }
  @supports (transition-behavior: allow-discrete) {
    .fd-faq::details-content {
      display: grid;
      grid-template-rows: 0fr;
      overflow: clip;
      transition:
        grid-template-rows var(--dur-base) var(--ease-out),
        content-visibility var(--dur-base) allow-discrete;
    }
    .fd-faq[open]::details-content {
      grid-template-rows: 1fr;
    }
    .fd-faq-answer {
      min-height: 0;
      overflow: hidden;
    }
  }
}

@media (max-width: 760px) and (prefers-reduced-motion: no-preference) {
  .fd-hero h1 .fd-line > span {
    animation-duration: var(--dur-slow);
    animation-delay: var(--stagger);
  }
  .fd-hero h1 .fd-line:nth-child(2) > span {
